CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_REVENUE_QUARTER_ACCOUNT_NAME
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_REVENUE at grain Date.FiscalYear, Date.Quarter, GLAccount.AccountName; covers 24.02% of weighted demand (1 clusters); est. 2,000 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.QUARTER,
       g2.ACCOUNT_NAME,
       SUM(f.AMOUNT) AS AMOUNT,
       SUM(f.KWH_SOLD) AS KWH_SOLD,
       SUM(f.REVENUE_PER_KWH) AS REVENUE_PER_KWH_SUM,
       COUNT(f.REVENUE_PER_KWH) AS REVENUE_PER_KWH_COUNT,
       COUNT(*) AS REVENUE_COUNT
FROM CORE.FCT_REVENUE f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
JOIN CORE.DIM_GL_ACCOUNT g2 ON f.GL_ACCOUNT_ID = g2.GL_ACCOUNT_ID
GROUP BY ALL;
